def transform(grid):
    h, w = len(grid), len(grid[0])

    # Full-width and full-height lines are the separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def intervals(size, separators):
        result = []
        start = 0
        for p in separators:
            if start < p:
                result.append((start, p))
            start = p + 1
        if start < size:
            result.append((start, size))
        return result

    row_blocks = intervals(h, sep_rows)
    col_blocks = intervals(w, sep_cols)

    background = grid[0][0]
    # Identify the most common non-separator color as the background.
    from collections import Counter
    counts = Counter(
        grid[r][c]
        for r in range(h) for c in range(w)
        if r not in sep_rows and c not in sep_cols
    )
    background = counts.most_common(1)[0][0]

    return [
        [
            1 if sum(
                grid[r][c] != background
                for r in range(r0, r1)
                for c in range(c0, c1)
            ) >= 2 else 5
            for c0, c1 in col_blocks
        ]
        for r0, r1 in row_blocks
    ]
